# Bám sách: trang 100–101 + đáp án + Mini dictionary unit 48. Không chép nguyên văn.
theory = (
 H("A", "Rain and snow", "Mưa và tuyết")
 + T([
    ("<b>beat down</b>", "Rain falls hard and in large amounts – the speaker hears it from bed.", "Mưa trút xuống mạnh và nhiều – người nói nằm trên giường nghe tiếng mưa."),
    ("<b>pelt down</b>", "(informal) Rain falls very heavily – by the time the walkers reached the mountain top.", "(thân mật) Mưa như trút – khi những người leo núi lên tới đỉnh."),
    ("<b>hold off</b>", "Snow that was expected did not start until they were safely home.", "Tuyết tưởng sẽ rơi nhưng chưa rơi cho tới khi họ về nhà an toàn."),
    ("<b>freeze up</b>", "In a very hard winter many people’s pipes got blocked with ice and stopped working.", "Mùa đông rất khắc nghiệt, ống nước nhà nhiều người bị đóng băng, tắc và hỏng."),
 ])
 + H("B", "Sun and clouds", "Mặt trời và mây")
 + T([
    ("<b>break through</b> (the clouds)", "The sun begins to appear from behind the clouds.", "Mặt trời bắt đầu ló ra sau đám mây."),
    ("<b>beat down</b>", "The sun shines very strongly and heats the air.", "Mặt trời chiếu rất gắt và làm không khí nóng lên."),
    ("<b>roll in</b>", "Bad weather such as cloud or fog arrives in large amounts.", "Thời tiết xấu như mây hay sương mù kéo đến dày đặc."),
    ("<b>blot out</b>", "Cloud or smoke covers the sun so that it cannot be seen.", "Mây hoặc khói che kín mặt trời."),
    ("<b>fog up</b> / <b>mist up</b> / <b>steam up</b>", "Windows or glasses get covered with tiny drops of water so you can’t see through them.", "Cửa kính hay kính đeo mắt bị phủ những giọt nước li ti nên không nhìn xuyên qua được."),
 ])
 + H("C", "Metaphors", "Ẩn dụ")
 + P("A worker describes the first day of a new boss, using weather words with a metaphorical meaning.", "Một nhân viên kể về ngày đầu tiên của sếp mới, dùng những từ chỉ thời tiết với nghĩa ẩn dụ.")
 + T([
    ("<b>breeze in</b>", "The new boss walked in quickly and confidently (a breeze is a light wind).", "Sếp mới bước vào nhanh và đầy tự tin (breeze là làn gió nhẹ)."),
    ("<b>breeze through</b>", "(slightly informal) He had passed the job interview very easily.", "(hơi thân mật) Ông ta đã vượt qua buổi phỏng vấn rất dễ dàng."),
    ("<b>cloud over</b>", "When he spoke to his PA, her face suddenly looked angry and unhappy.", "Khi ông nói với trợ lý riêng, mặt cô ấy bỗng sa sầm vì giận."),
    ("<b>freeze up</b>", "The sales manager was so frightened by his aggressive questions that she could not speak.", "Trưởng phòng kinh doanh sợ những câu hỏi hung hăng của ông đến mức cứng họng."),
    ("<b>mist over</b>", "Her eyes filled with tears.", "Mắt cô ấy rưng rưng nước mắt."),
    ("<b>storm out</b>", "By the end of the day the PA had left angrily, saying she would never come back.", "Cuối ngày, cô trợ lý giận dữ bỏ đi, nói sẽ không bao giờ quay lại."),
    ("<b>freeze out</b>", "The staff agreed to be unfriendly so he would feel unwelcome, speaking to him only when necessary.", "Các nhân viên thống nhất lạnh nhạt để ông thấy mình không được chào đón, chỉ nói chuyện khi thật cần."),
 ])
 + NOTE("<b>Exercise 48.2 and its key</b>: pipes that freeze up will probably burst later and cause damage; freezing up before a wedding speech means you are too nervous to speak; being frozen out by friends means they want to exclude you. <b>48.4</b>: you breeze in ‘as if nothing had happened’; fog rolls in ‘from the sea/hills/moors’.",
        "<b>Bài 48.2 và đáp án</b>: ống nước bị đóng băng có thể vỡ sau đó và gây hư hại; cứng người trước bài phát biểu đám cưới là vì quá lo lắng; bị bạn bè ‘freeze out’ là họ muốn gạt bạn ra. <b>48.4</b>: bước vào ‘như chưa có chuyện gì’; sương mù kéo đến ‘từ biển/đồi/vùng đồng hoang’.")
)
